\label{defintion: codeword}
For some ${\mathcal{V}} \subseteq [K]$ and an arbitrary $\theta^{k}_{{\mathcal{P}}_{k}, q_{k}} \in \mathbb{C}$, the superposition signal 

   \begin{equation}
   \sum_{k \in {\mathcal{V}}} \theta^{k}_{{\mathcal{P}}_{k}, q_{k}} {\mathsf{c}} \left( W^{k}_{{\mathcal{P}}_{k}, q_{k}} \right),
   \end{equation}

is defined as a \emph{codeword} of size $\left\lvert {\mathcal{V}} \right\rvert$, where ${\mathcal{P}}_{k} \subseteq [K]$ with $\left\lvert {\mathcal{P}}_{k} \right\rvert=t$, $q_{k} \in [\binom{K-t-1}{L-1}]$, and 

${\mathsf{c}} \left( W^{k}_{{\mathcal{P}}_{k}, q_{k}} \right) $ is the encoded signal of $ W^{k}_{{\mathcal{P}}_{k}, q_{k}}$ with ${\mathsf{c}}: \mathbb{F}_{2^{f}} \rightarrow \mathbb{C}$.

For the subset ${\mathcal{Q}} \subseteq [t+L]$ with $\lvert {\mathcal{Q}} \rvert = t+1$, define the beamforming (row) vector ${\mathbf{v}}_{{\mathcal{Q}}} \in \mathbb{C}^{1 \times L}$ as follows
\begin{equation}
    \begin{aligned}
        \begin{cases}
            {\mathbf{v}}_{{\mathcal{Q}}}  {\mathbf{h}}_{k} = 0 & k \in [t+L] \text{ and } k \notin {\mathcal{Q}} \\
            {\mathbf{v}}_{{\mathcal{Q}}}  {\mathbf{h}}_{k} \neq 0 & k \in {\mathcal{Q}}
        \end{cases}.
    \end{aligned}
\end{equation}

\label{theorem: load UL A}
   Using the proposed UL transmission strategy, during stage 1, the BS is able to create all codewords of size $t+1$ in the set ${\mathcal{A}} \, \cup \, {\mathcal{B}}$, where
   \begin{equation}
    \label{eq: set A def}
        \begin{array}{c}
             {\mathcal{A}}  =  \Big\lbrace  \sum\limits_{k \in {\mathcal{S}}} {\mathbf{v}}_{{\mathcal{S}}} {\mathbf{h}}_{k} {\mathsf{c}} \big( W^{\left< k \right>_{{\mathcal{S}}}}_{{\mathcal{S}} \backslash \lbrace  \left< k \right>_{{\mathcal{S}}} \rbrace ,q} \big) +  {\mathbf{v}}_{{\mathcal{S}}} {\mathbf{n}}_{\rm BS} : {\mathcal{S}} \in {\mathcal{M}}  \Big\rbrace,
        \end{array}
    \end{equation}
    \begin{equation}
     \label{eq: set B ref}
         \begin{array}{c}
            {\mathcal{B}}= \Big\lbrace   \sum\limits_{k \in {\mathcal{R}} }  - {\mathbf{v}}_{{\mathcal{R}}} {\mathbf{h}}_{k}  {\mathsf{c}} \big( W^{\left< k \right>_{{\mathcal{R}}}}_{{\mathcal{R}} \backslash \lbrace  \left< k \right>_{{\mathcal{R}} } \rbrace  ,q} \big)  + {\mathbf{v}}_{{\mathcal{R}} } {\mathbf{n}}_{\rm BS} :  \\
              {\mathcal{R}} \subseteq \left[ 2: t+L \right], \left\vert {\mathcal{R}} \right\vert=t+1  \Big\rbrace
         \end{array}
     \end{equation}
    include noisy versions of the codewords of size $t+1$ (that are needed in the DL step).
   Moreover, the NDT for UL is                     
   \begin{equation}
   \label{eq: R UL A}
       \begin{aligned}
           T_{\rm UL} = \frac{K-t}{t+L}.
       \end{aligned}
   \end{equation}

\label{theorem: DL}
    By adopting the introduced DL transmission strategy, each user is able to retrieve its requested file, and the achievable NDT for the DL step takes the form of:
    \begin{equation}
   \label{eq: R DL A}
       \begin{aligned}
           T_{\rm DL} = \frac{K-t}{t+L}.
       \end{aligned}
   \end{equation}
